export default function build({ THREE, add, task }) {
  const v3 = (x, y, z) => new THREE.Vector3(x, y, z);
  const eulerFromBasis = (ex, ey, ez) => {
    const m = new THREE.Matrix4().makeBasis(ex, ey, ez);
    const e = new THREE.Euler().setFromRotationMatrix(m, 'XYZ');
    return [e.x, e.y, e.z];
  };

  function addChannel(p0, p1, innerW, floorT, wallH, wallT, wallYOffset = 0) {
    const a = v3(...p0);
    const b = v3(...p1);
    const d = b.clone().sub(a);
    const L = d.length();
    const ex = d.clone().normalize();
    const ez = v3(-d.z, 0, d.x).normalize();
    const ey = new THREE.Vector3().crossVectors(ez, ex).normalize();
    const rot = eulerFromBasis(ex, ey, ez);
    const mid = a.clone().add(b).multiplyScalar(0.5);

    const floorWidth = innerW + 2 * wallT;
    const floorPos = mid.clone().addScaledVector(ey, -floorT / 2);
    add.box({
      size: [L, floorT, floorWidth],
      position: [floorPos.x, floorPos.y, floorPos.z],
      rotation: rot,
      color: '#d9b382',
    });

    for (const side of [-1, 1]) {
      const wallPos = mid
        .clone()
        .addScaledVector(ey, wallH / 2 + wallYOffset)
        .addScaledVector(ez, side * (innerW / 2 + wallT / 2));
      add.box({
        size: [L, wallH, wallT],
        position: [wallPos.x, wallPos.y, wallPos.z],
        rotation: rot,
        color: '#8c5a32',
      });
    }
  }

  // Start is [-0.85, 0.8, -0.3], cup is [0.8, 0, 0.3]
  // Behind start via center height 0.36 to cup rim
  const pStart = [-0.95, 0.68, -0.34];
  const pMid = [-0.08, 0.36, -0.025];
  const pEnd = [0.73, 0.065, 0.275];

  addChannel(pStart, pMid, 0.065, 0.012, 0.06, 0.012, -0.005);
  addChannel(pMid, pEnd, 0.065, 0.012, 0.06, 0.012, -0.005);

  // Funnel walls behind cup
  // Cup center is [0.8, 0, 0.3], innerRadius 0.07, wallHeight 0.06
  // Direction of ramp in xz is roughly (0.94, 0.34), angle ~ 0.35 rad
  const angle = Math.atan2(0.6, 1.65);
  const fLen = 0.22;
  const fH = 0.14;
  const fT = 0.012;
  const spread = 0.65; // radians half-angle of V funnel

  // Apex behind cup along ramp direction
  const apexX = 0.8 + 0.095 * Math.cos(angle);
  const apexZ = 0.3 + 0.095 * Math.sin(angle);

  for (const side of [-1, 1]) {
    const dirAngle = angle + Math.PI + side * spread;
    const cx = apexX + (fLen / 2) * Math.cos(dirAngle);
    const cz = apexZ + (fLen / 2) * Math.sin(dirAngle);
    add.box({
      size: [fLen, fH, fT],
      position: [cx, fH / 2, cz],
      rotation: [0, -dirAngle, 0],
      color: '#6b4423',
    });
  }
}

